function paintAttributes(b){const f=CpuAurora.sample(b),a=[];const put=(id,k,v)=>a.push([id,k,String(v)]),pts=p=>p.map(q=>q.join(',')).join(' ');put('cpu-svg','color',f.color);put('cpu-scene','filter',f.state==='U'?'url(#CPU_LIFT_UNKNOWN)':'none');b.modules.forEach((m,i)=>put('module-'+i,'transform',m.transform));f.columns.forEach(c=>{put('aurora-column-'+c.index,'opacity',c.opacity);put('aurora-front-'+c.index,'points',pts(c.front));put('aurora-side-'+c.index,'points',pts(c.side));c.ribbons.forEach((d,j)=>put('aurora-ribbon-'+c.index+'-'+j,'d',d))});f.transactions.forEach(t=>put('access-route-'+t.index,'points',pts(t.path)));f.hits.forEach((h,i)=>{put('cache-response-'+i,'fill-opacity',f.state==='U'||f.reduced?.045:.10+h*.36);put('cache-response-'+i,'stroke-width',.9+h*.85);put('cache-response-'+i,'stroke-opacity',f.state==='U'?.25:.68+h*.32)});f.particles.forEach(p=>{put('particle-'+p.id,'d',p.d);put('particle-'+p.id,'opacity',p.opacity)});return a}

function createCpuBridge(env,makeController,paint){let root=null,nodes=new Map(),controller=null,frameId=null,epoch=0;function cancel(){if(frameId!==null){env.caf(frameId);frameId=null}}function active(){return root&&root.isConnected&&!controller.paused&&!controller.reduced&&controller.state!=='U'}function apply(frame){for(const [id,k,v] of paint(frame)){const el=nodes.get(id);if(!el)throw Error('CPU mount missing id '+id);el.setAttribute(k,v)}}function schedule(){if(!active()||frameId!==null)return;const ticket=epoch;frameId=env.raf(stamp=>{if(ticket!==epoch)return;frameId=null;if(!root||!root.isConnected||env.findRoot()!==root){sync();return}apply(controller.advance(stamp));schedule()})}function sync(){const stamp=env.now(),next=env.findRoot();if(next!==root){cancel();epoch++;root=next;nodes=new Map();if(root){nodes.set(root.id,root);for(const el of root.querySelectorAll('[id]'))nodes.set(el.id,el)}}if(!root||!root.isConnected){cancel();if(controller&&!controller.paused)controller.setPaused(true,stamp);return}const state=env.getState(root);if(!controller)controller=makeController(state,stamp);else if(controller.state!==state)controller.setState(state,stamp);if(controller.reduced!==env.getReduced())controller.setReduced(env.getReduced(),stamp);if(controller.paused===env.getPlaying())controller.setPaused(!env.getPlaying(),stamp);apply(controller.advance(stamp));if(active())schedule();else cancel()}function destroy(){cancel();epoch++;if(controller&&!controller.paused)controller.setPaused(true,env.now());root=null;nodes=new Map()}return {sync,destroy,inspect(){return {mounted:!!root,pending:frameId!==null,epoch,frame:controller?controller.read():null}}}}


